# Generates kaliru/src/extras/tmc_tables.rs from Kalico's tmc driver modules
# (Registers, ReadRegisters, Fields, SignedFields, TMC_FREQUENCY, MAX_CURRENT)
# usage (reference venv, from ~/rk/kalico):
#   .venv/bin/python /mnt/d/RustyKlipper/kaliru/tools/gen_tmc_tables.py > src/extras/tmc_tables.rs
import importlib
import sys

sys.path.insert(0, ".")
CHIPS = ["tmc2130", "tmc2208", "tmc2209", "tmc2240", "tmc2660", "tmc5160", "tmc5262"]

out = ["// Register tables of Kalico's tmc drivers, generated by tools/gen_tmc_tables.py",
       "// (do not edit: regenerate from klippy/extras/tmc*.py)", ""]
for chip in CHIPS:
    m = importlib.import_module("klippy.extras." + chip)
    out.append("pub mod %s {" % chip)
    if hasattr(m, "TMC_FREQUENCY"):
        out.append("    pub const TMC_FREQUENCY: f64 = %r;" % m.TMC_FREQUENCY)
    if hasattr(m, "MAX_CURRENT"):
        out.append("    pub const MAX_CURRENT: f64 = %r;" % m.MAX_CURRENT)
    regs = ", ".join('("%s", 0x%x)' % (k, v) for k, v in m.Registers.items())
    out.append("    pub const REGISTERS: &[(&str, i64)] = &[%s];" % regs)
    rr = ", ".join('"%s"' % r for r in m.ReadRegisters)
    out.append("    pub const READ_REGISTERS: &[&str] = &[%s];" % rr)
    out.append("    pub const FIELDS: &[(&str, &[(&str, i64)])] = &[")
    for reg, fields in m.Fields.items():
        fs = ", ".join('("%s", 0x%x)' % (f, mask) for f, mask in fields.items())
        out.append('        ("%s", &[%s]),' % (reg, fs))
    out.append("    ];")
    signed = getattr(m, "SignedFields", None)
    if signed is None:
        # tmc2209 builds its FieldHelper with tmc2208.SignedFields
        signed = importlib.import_module("klippy.extras.tmc2208").SignedFields
    sf = ", ".join('"%s"' % f for f in signed)
    out.append("    pub const SIGNED_FIELDS: &[&str] = &[%s];" % sf)
    ff = ", ".join('"%s"' % f for f in m.FieldFormatters)
    out.append("    /// the fields with a FieldFormatters entry")
    out.append("    pub const FORMATTED_FIELDS: &[&str] = &[%s];" % ff)
    out.append("}")
    out.append("")
print("\n".join(out))
